{
  "technical_and_design_decisions": [
    "Port the five XD modules as Spring Cloud Stream processor components using the repository's existing module conventions and functional programming model where applicable.",
    "Preserve externally observable XD behavior and configuration names unless they conflict with Spring Cloud Stream conventions or current repository APIs.",
    "Implement json-to-tuple and object-to-json using the repository's existing Jackson and message-conversion facilities rather than introducing a separate serialization framework.",
    "Implement script with a constrained, configurable scripting integration and avoid adding new scripting languages beyond those already supported by the repository.",
    "Implement shell as a processor that invokes an operating-system command through a controlled process abstraction, with configurable command, arguments, environment, timeout, and error handling.",
    "Implement splitter using Spring messaging-compatible splitting semantics and preserve message headers where supported by the existing framework.",
    "For composed jobs, first evaluate lifecycle and recovery dependencies, then remove obsolete composed-job resources only where they are no longer required by active job execution.",
    "Persist composed-job definitions in ZooKeeper metadata using a versioned, namespaced representation that supports retrieval and reconstruction after failure.",
    "Introduce BinderFactory as an interface-based abstraction with a default implementation for the currently supported binder and extension points for future binder types.",
    "Use unit tests for transformation and configuration behavior, focused integration tests for Spring Cloud Stream wiring, and regression tests for job metadata and binder lifecycle behavior."
  ],
  "assumptions": [
    "The existing s-c-s repository builds successfully and provides standard module, messaging, configuration, test, and ZooKeeper integration infrastructure.",
    "The XD source implementations, documentation, and representative tests are available for reference and can be legally reused or adapted.",
    "The increment targets Java 17 or later and the repository's existing Spring Framework and Spring Cloud Stream versions.",
    "No major repository-wide migration, dependency upgrade, or redesign outside the stated user stories is required.",
    "Existing serialization, scripting, shell execution, ZooKeeper client, and binder dependencies may be reused; new dependencies require only normal review and integration work.",
    "The five ported modules require compatibility with the primary existing binder and do not require simultaneous support for multiple production binders.",
    "The composed-job stories include implementation of the selected cleanup and ZooKeeper persistence approach, not merely a written investigation report.",
    "ZooKeeper availability, security configuration, and operational deployment are already handled by the surrounding platform.",
    "One developer performs the work, and estimates include coding, local testing, review preparation, and defect correction but exclude elapsed waiting time.",
    "No dedicated performance, penetration, or production migration exercise is required beyond targeted regression and error-path testing."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Repository and XD implementation analysis",
      "activity_description": "Review the s-c-s architecture, module conventions, supported Spring versions, existing processor implementations, relevant XD source code, configuration formats, test patterns, and integration points.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A2",
      "activity_name": "Build, dependency, and compatibility setup",
      "activity_description": "Prepare module structure, dependency declarations, Java 17 and Spring compatibility adjustments, configuration metadata, and local development fixtures required by the ported components.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "Port json-to-tuple processor",
      "activity_description": "Implement the JSON-to-tuple transformation, map configuration and message behavior from XD, and add focused unit and integration coverage.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A4",
      "activity_name": "Port object-to-json processor",
      "activity_description": "Implement object serialization to JSON, preserve expected headers and payload behavior, expose supported configuration, and add tests for normal and error cases.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Port script processor",
      "activity_description": "Port script evaluation and payload handling, implement configuration and failure behavior, integrate with the supported scripting facilities, and add representative tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A6",
      "activity_name": "Port shell processor",
      "activity_description": "Implement command execution, input and output handling, process failure and timeout behavior, configuration binding, and tests with controlled command fixtures.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7",
      "activity_name": "Port splitter processor",
      "activity_description": "Implement message splitting behavior, output emission, header propagation, configurable delimiters or strategies where applicable, and unit and integration tests.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A8",
      "activity_name": "Cross-module tests, configuration, and documentation",
      "activity_description": "Complete shared test utilities, module metadata, examples, configuration reference, compatibility checks, and consistency fixes across all five ported processors.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A9",
      "activity_name": "Composed-job removal analysis and implementation",
      "activity_description": "Trace composed-job creation, execution, cleanup, and resource ownership; select a safe removal strategy; implement cleanup of obsolete resources; and add lifecycle regression tests.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A10",
      "activity_name": "Composed-job definition persistence in ZooKeeper",
      "activity_description": "Design the metadata schema and lifecycle, implement storing and retrieving composed-job definitions, integrate recovery or recreation behavior, and test missing, stale, and malformed metadata scenarios.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A11",
      "activity_name": "BinderFactory abstraction",
      "activity_description": "Define the BinderFactory contract, implement the adapter for the current binder, refactor callers, add configuration and extension points for future binder types, and provide unit and integration coverage.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "End-to-end integration and regression validation",
      "activity_description": "Run the full build and representative streaming pipelines, verify module interoperability, validate ZooKeeper and binder behavior, fix integration defects, and update CI-related checks.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A13",
      "activity_name": "Final review and delivery preparation",
      "activity_description": "Perform code cleanup, API and configuration review, finalize documentation and release notes, inspect test coverage, and prepare the increment for submission.",
      "most_likely_effort": 2
    }
  ],
  "reported_total": {
    "most_likely_effort": 55
  }
}

